  "summary": "The code contained a critical OS Command Injection vulnerability and blocking I/O operations. I have replaced the shell execution with the 'sharp' library for secure, asynchronous image processing and added input sanitization. Overall code health is significantly improved by adopting modern, non-blocking practices.",
  "fixed_code": "const express = require('express');
const sharp = require('sharp');
const path = require('path');
const rateLimit = require('express-rate-limit');

const app = express();
const UPLOADS_DIR = 'uploads';
const THUMBS_DIR = 'thumbs';

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});

/**
 * Generates a thumbnail for the requested image file.
 * @param {string} req.query.file - The filename of the image to process.
 */
app.get('/thumbnail', limiter, async (req, res) => {
  const rawFile = req.query.file;
  if (!rawFile) {
    return res.status(400).json({ error: 'file required' });
  }

  const safeFile = path.basename(rawFile);
  const inputPath = path.join(UPLOADS_DIR, safeFile);
  const outputPath = path.join(THUMBS_DIR, `${safeFile}.png`);

  try {
    await sharp(inputPath)
      .resize(200, 200)
      .toFile(outputPath);
    res.json({ thumbnail: `/thumbs/${safeFile}.png` });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Processing failed' });
  }
});

app.listen(3000);"
